function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$root=dirname(__DIR__);$source=(string)file_get_contents($root.'/generate_invoice_pdf.php');
foreach(['<th>Наименование</th>','table-header-group','page-break-inside: avoid','class="final-block"','Доставка — стоимость согласовывается','min_screen_size','sellerRegistrationDate','sellerBankAccount','sellerVatNotice'] as $needle)check(str_contains($source,$needle),"generator missing {$needle}");
